--- Button component.
---
--- Returns a normalized button spec with auto-generated id.
--- Ids are stable when provided, allowing dynamic widget usage.

local M = {}

local counter = 0

--- Reset the auto-id counter. Called once per render pass so autogenerated
--- ids stay stable across frames (hover state set on frame N must match the
--- id regenerated on frame N+1).
function M.reset()
  counter = 0
end

---@param opts { id?: string, text: string, kind?: "default"|"primary"|"destructive", on_click?: fun(e: { id: string }) }
---@return HollowUiDialogButton
function M.button(opts)
  opts = opts or {}
  if type(opts.text) ~= "string" or opts.text == "" then
    error("dialog buttons require a 'text' string")
  end

  counter = counter + 1
  local id = opts.id or ("dialog:button:" .. counter)

  return {
    _button = true,
    id = id,
    text = opts.text,
    kind = opts.kind or "default",
    on_click = opts.on_click,
  }
end

return M
